<script setup>import {ref} from 'vue';import {state,actions} from '../../domain/prototypeStore.js';import StatusTag from '../../components/StatusTag.vue';const msg=ref('');const advance=()=>{const r=actions.advanceDrill();msg.value=r.message||(r.ok?'演练状态已推进':'操作失败')}</script>
<template><section class="page-stack"><div class="page-heading"><div class="module-icon">演</div><div><h2>演练闭环</h2><p>计划、执行、结果、评估和改进</p></div><StatusTag :text="state.drill.status"/></div><div v-if="msg" class="action-message">{{msg}}</div>
<article class="panel detail-grid"><div><small>演练编号</small><strong>{{state.drill.id}}</strong></div><div><small>演练名称</small><strong>{{state.drill.name}}</strong></div><div><small>场所</small><strong>{{state.drill.place}}</strong></div><div><small>责任组</small><strong>{{state.drill.owner}}</strong></div><div><small>执行结果</small><strong>{{state.drill.result||'待提交'}}</strong></div><div><small>改进措施</small><strong>{{state.drill.improvement||'待评估'}}</strong></div></article>
<div class="button-row"><button class="primary-button active" :disabled="state.drill.status==='已完成'" @click="advance">{{state.drill.status==='待执行'?'启动演练':state.drill.status==='执行中'?'提交执行结果':state.drill.status==='待评估'?'完成评估':'演练已完成'}}</button><RouterLink class="secondary-link" to="/h5/drills">H5 执行入口</RouterLink></div></section></template>